NAME "Blue Arena 150"

TEXTURE tiles assets/textures/blue_tiles.png
TEXTURE corrugate assets/textures/corrugate.png
TEXTURE concrete assets/textures/gray_concrete.png
TEXTURE crate assets/textures/crate_128.png
TEXTURE bricks assets/textures/dark_bricks.png

GEOMETRY crate assets/models/crate.obj

MATERIAL mat_tiles tiles NULL (1,1,1)
MATERIAL mat_corrugate corrugate NULL (1,1,1)
MATERIAL mat_concrete concrete NULL (1,1,1)
MATERIAL mat_crate crate NULL (1,1,1)
MATERIAL mat_bricks bricks NULL (1,1,1)

# --- OUTER WALLS (Boundary 150 units) ---
# Walls are 10 units high, 2 units thick. Inner space is 148x148.
# North Wall
INSTANCE cube mat_bricks 4.0 (0,5,-76) (75,5,1) (0,0,0)
# South Wall
INSTANCE cube mat_bricks 4.0 (0,5,76) (75,5,1) (0,0,0)
# West Wall
INSTANCE cube mat_bricks 4.0 (-76,5,0) (1,5,75) (0,0,0)
# East Wall
INSTANCE cube mat_bricks 4.0 (76,5,0) (1,5,75) (0,0,0)

# --- FLOOR ---
# Main floor slightly below zero to prevent z-fighting with walls
INSTANCE plane mat_tiles 30.0 (0,-0.1,0) (75,1,75) (0,0,0)

# --- ELEVATIONS & PLATFORMS ---

# Central Raised Platform (Tiered)
# Base tier
INSTANCE cube mat_concrete 8.0 (0,1,0) (20,1,20) (0,0,0)
# Upper tier
INSTANCE cube mat_concrete 6.0 (0,3,0) (12,1,12) (0,0,0)
# Top platform surface
INSTANCE plane mat_corrugate 4.0 (0,4.01,0) (6,1,6) (0,0,0)

# NW Corner Elevated Bunker Area
INSTANCE cube mat_concrete 5.0 (-45,2,-45) (18,2,18) (0,0,0)
INSTANCE plane mat_corrugate 3.0 (-45,4.01,-45) (9,1,9) (0,0,0)
# Ramp to NW bunker (stair-step approximation using cubes)
INSTANCE cube mat_concrete 2.0 (-32,0.5,-32) (4,0.5,4) (0,0,0)
INSTANCE cube mat_concrete 2.0 (-36,1.5,-36) (4,0.5,4) (0,0,0)
INSTANCE cube mat_concrete 2.0 (-40,2.5,-40) (4,0.5,4) (0,0,0)

# SE Corner Symmetric Bunker Area
INSTANCE cube mat_concrete 5.0 (45,2,45) (18,2,18) (0,0,0)
INSTANCE plane mat_corrugate 3.0 (45,4.01,45) (9,1,9) (0,0,0)
# Ramp to SE bunker
INSTANCE cube mat_concrete 2.0 (32,0.5,32) (4,0.5,4) (0,0,0)
INSTANCE cube mat_concrete 2.0 (36,1.5,36) (4,0.5,4) (0,0,0)
INSTANCE cube mat_concrete 2.0 (40,2.5,40) (4,0.5,4) (0,0,0)

# NE Long Elevated Walkway
INSTANCE cube mat_concrete 3.0 (40,1.5,-40) (6,1.5,25) (0,0,0)
INSTANCE plane mat_corrugate 2.0 (40,3.01,-40) (3,1,12.5) (0,0,0)

# SW Cover Blocks (ground level obstacles)
INSTANCE cube mat_bricks 2.0 (-40,1.5,30) (3,1.5,3) (0,0,0)
INSTANCE cube mat_bricks 2.0 (-30,1.5,40) (3,1.5,3) (0,0,0)
INSTANCE cube mat_bricks 2.0 (-50,1.5,50) (3,1.5,3) (0,0,0)

# --- CRATE PROPS ---
# Crates placed strategically for cover and visual interest

# Center platform crates
INSTANCE crate mat_crate 1.0 (3,4.5,2) (1,1,1) (0,15,0)
INSTANCE crate mat_crate 1.0 (-2,4.5,-3) (1,1,1) (0,45,0)
INSTANCE crate mat_crate 1.0 (0,5.5,0) (1,1,1) (0,0,0)

# NW Bunker crates
INSTANCE crate mat_crate 1.0 (-48,4.5,-48) (1,1,1) (0,30,0)
INSTANCE crate mat_crate 1.0 (-43,4.5,-42) (1,1,1) (0,60,0)
INSTANCE crate mat_crate 1.0 (-46,5.5,-45) (1,1,1) (0,10,0)

# SE Bunker crates
INSTANCE crate mat_crate 1.0 (47,4.5,47) (1,1,1) (0,20,0)
INSTANCE crate mat_crate 1.0 (42,4.5,43) (1,1,1) (0,70,0)

# NE Walkway crates
INSTANCE crate mat_crate 1.0 (40,3.5,-50) (1,1,1) (0,0,0)
INSTANCE crate mat_crate 1.0 (40,3.5,-35) (1,1,1) (0,45,0)

# Ground level scattered crates
INSTANCE crate mat_crate 1.0 (15,0.5,20) (1,1,1) (0,25,0)
INSTANCE crate mat_crate 1.0 (-20,0.5,-15) (1,1,1) (0,80,0)
INSTANCE crate mat_crate 1.0 (25,0.5,-25) (1,1,1) (0,10,0)
INSTANCE crate mat_crate 1.0 (-10,0.5,55) (1,1,1) (0,55,0)
INSTANCE crate mat_crate 1.0 (60,0.5,10) (1,1,1) (0,35,0)
INSTANCE crate mat_crate 1.0 (-60,0.5,-10) (1,1,1) (0,65,0)

# Stacked crates near SW cover blocks
INSTANCE crate mat_crate 1.0 (-40,0.5,33) (1,1,1) (0,0,0)
INSTANCE crate mat_crate 1.0 (-40,1.5,33) (1,1,1) (0,30,0)

# --- LIGHTING ---
# Main directional sun light
LIGHT directional (0,50,-30) 1.2 1000.0 (-0.3,-1,0.5) (1,0.95,0.9)

# Fill point lights for arena visibility
LIGHT point (0,20,0) 0.8 10.0 (0.9,0.95,1) NULL
LIGHT point (-45,12,-45) 0.5 10.0 (0.8,0.9,1) NULL
LIGHT point (45,12,45) 0.5 10.0 (0.8,0.9,1) NULL
LIGHT point (40,10,-40) 0.4 10.0 (0.85,0.9,1) NULL
LIGHT point (0,8,60) 0.3 10.0 (0.9,0.9,1) NULL
LIGHT point (0,8,-60) 0.3 10.0  (0.9,0.9,1) NULL